      "content": "{\n  \"name\": \"@ljwei-stak/dsh-model-router\",\n  \"version\": \"0.25.5\",\n  \"type\": \"module\",\n  \"description\": \"Model Router for official DeepSeek Harness Desktop: cost-aware task routing, dependent work packages and official vendor CLI discovery, installation and execution. GAL is available separately as @ljwei-stak/dsh-galgame.\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Alice-Marx/dsh-model-router.git\"\n  },\n  \"homepage\": \"https://github.com/Alice-Marx/dsh-model-router#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Alice-Marx/dsh-model-router/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"main\": \"./.dsh-plugin/index.mjs\",\n  \"exports\": {\n    \".\": \"./.dsh-plugin/index.mjs\",\n    \"./client\": \"./.dsh-plugin/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-api-session-controller\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\"\n      ]\n    }\n  },\n  \"files\": [\n    \".dsh-plugin/index.mjs\",\n    \".dsh-plugin/official-tools-remote-service.mjs\",\n    \".dsh-plugin/client.js\",\n    \".dsh-plugin/shared/harness-plan.mjs\",\n    \".dsh-plugin/shared/model-profiles.mjs\",\n    \".dsh-plugin/shared/router.mjs\",\n    \".dsh-plugin/shared/assignment-solver.mjs\",\n    \".dsh-plugin/shared/adaptive-feedback.mjs\",\n    \".dsh-plugin/shared/dynamic-data.mjs\",\n    \".dsh-plugin/shared/dynamic-data-view.mjs\",\n    \".dsh-plugin/shared/livebench.mjs\",\n    \".dsh-plugin/shared/official-tool-registr